/** Raw construction fixtures/live pigs/ore only. Every preparation, timer and meal is actual. */
public final class CuredPorkFlowTest implements FabricClientGameTest {
    private static final BlockPos TABLE=new BlockPos(0,100,2),BOARD=new BlockPos(2,100,0),MILL=new BlockPos(-2,100,0),JAR=new BlockPos(4,100,0),BAD=new BlockPos(6,100,0),RACK=new BlockPos(4,100,3),FURNACE=new BlockPos(0,100,0),ORE=new BlockPos(-5,100,3);
    private static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
    private static KitchenBlockEntity be(net.minecraft.server.MinecraftServer s,BlockPos at){return (KitchenBlockEntity)s.overworld().getBlockEntity(at);}
    private static boolean observe(SurvivalPlayer p,java.util.function.Predicate<net.minecraft.server.MinecraftServer> test){boolean[] v={false};p.s.runOnServer(s->v[0]=test.test(s));return v[0];}
    private static void near(SurvivalPlayer p,BlockPos at){p.s.runCommand("tp @a "+(at.getX()+.5)+" 100 "+(at.getZ()-2.5));p.c.waitTicks(4);}
    private static void tap(SurvivalPlayer p,BlockPos at){near(p,at);p.click(at,Direction.UP);}
    private static void put(SurvivalPlayer p,String id,BlockPos at,int n){for(int i=0;i<n;i++){p.select(id.contains(":")?id:"smoke_kitchen:"+id);tap(p,at);}}
    private static void take(SurvivalPlayer p,BlockPos at){p.emptyHand();p.c.getInput().holdKey(o->o.keyShift);tap(p,at);p.c.getInput().releaseKey(o->o.keyShift);}
    private static void cell(SurvivalPlayer p,int slot){near(p,RACK);var v=new Vec3(RACK.getX()+(3+5*(slot%3))/16d,RACK.getY()+(slot<3?.3:.7),RACK.getZ()+7/16d);p.look(v);p.c.runOnClient(m->m.gameMode.useItemOn(m.player,InteractionHand.MAIN_HAND,new BlockHitResult(v,Direction.NORTH,RACK,false)));p.c.waitTicks(6);}
    private static net.minecraft.nbt.CompoundTag data(ItemStack s){return s.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();}
    private static void photo(SurvivalPlayer p,String stage,BlockPos at){p.emptyHand();p.s.runCommand("time set noon");p.s.runCommand("tp @a "+(at.getX()+2.5)+" 100 "+(at.getZ()-3.5));p.c.waitTicks(6);p.look(Vec3.atCenterOf(at));p.c.runOnClient(m->{m.options.fov().set(42);m.getToastManager().clear();});p.c.waitTicks(25);p.c.takeScreenshot("curing-"+stage+"-0.1.23");p.c.runOnClient(m->m.options.fov().set(70));}
    private static void waitWorld(SurvivalPlayer p,int n,String phase){SpiceChainFlowTest.waitWorld(p,n,phase);}
    private static void cookOne(SurvivalPlayer p){p.emptyHand();tap(p,FURNACE);p.putInMenu("smoke_kitchen:dried_salted_pork",0,1);p.closeMenu();waitWorld(p,250,"原版熔炉真实加热");p.emptyHand();tap(p,FURNACE);check(p.c.computeOnClient(m->m.player.containerMenu.getSlot(2).getItem().is(KitchenContent.item("cooked_salted_pork"))),"Actual furnace produces cooked cured meat");p.c.takeScreenshot("curing-actual-vanilla-furnace-output-0.1.23");p.slot(2,0,ContainerInput.QUICK_MOVE);p.closeMenu();}
    @Override public void runTest(ClientGameTestContext c){TestWorldSave save;int[] curingAtTake={0};Set<Long> dates=new HashSet<>();
        try(var w=c.worldBuilder().create()){
            save=w.getWorldSave();var p=new SurvivalPlayer(c,w.getServer());p.s.runCommand("gamemode survival @a");p.s.runCommand("difficulty peaceful");p.s.runCommand("fill -8 98 -6 12 99 8 minecraft:smooth_stone");p.s.runCommand("weather clear 10000");p.s.runCommand("time set noon");
            for(String raw:new String[]{"minecraft:oak_log 8","minecraft:cobblestone 24","minecraft:terracotta 10","minecraft:string 2","minecraft:glass 3","minecraft:coal 3","minecraft:book","minecraft:wheat_seeds"})p.s.runCommand("give @a "+raw);near(p,TABLE);
            if(net.fabricmc.loader.api.FabricLoader.getInstance().isModLoaded("iris"))c.runOnClient(m->{try{var a=Class.forName("net.irisshaders.iris.api.v0.IrisApi");check((Boolean)a.getMethod("isShaderPackInUse").invoke(a.getMethod("getInstance").invoke(null)),"Actual Iris pack must be enabled");}catch(ReflectiveOperationException e){throw new AssertionError(e);}});
            for(int i=0;i<8;i++)p.craft("oak_planks","oak_log");p.craft("crafting_table","oak_planks","oak_planks","oak_planks","oak_planks");p.closeMenu();p.select("crafting_table");tap(p,TABLE.below());p.emptyHand();tap(p,TABLE);for(int i=0;i<5;i++)p.craft("stick","oak_planks","","","oak_planks","","");p.craft("stone_axe","cobblestone","cobblestone","","cobblestone","stick","","","stick","");p.craft("stone_pickaxe","cobblestone","cobblestone","cobblestone","","stick","","","stick","");p.craft("furnace","cobblestone","cobblestone","cobblestone","cobblestone","","cobblestone","cobblestone","cobblestone","cobblestone");p.craft("smoke_kitchen:hand_mill","","stick","","cobblestone","cobblestone","cobblestone","cobblestone","cobblestone","cobblestone");p.craft("smoke_kitchen:stone_knife","","cobblestone","","cobblestone","","","stick","","");p.craft("smoke_kitchen:cutting_board","oak_planks","oak_planks","oak_planks","","stick","","stick","","");for(int i=0;i<2;i++){p.craft("smoke_kitchen:wooden_lid","oak_planks","oak_planks","","","stick","");p.craft("smoke_kitchen:pickling_crock","terracotta","terracotta","terracotta","terracotta","terracotta","smoke_kitchen:wooden_lid");}p.craft("smoke_kitchen:drying_rack","stick","","stick","oak_planks","string","oak_planks","stick","string","stick");p.craft("smoke_kitchen:empty_jar","glass","glass","glass","oak_planks");p.craft("smoke_kitchen:recipe_book","book","wheat_seeds");p.closeMenu();
            for(var a:new BlockPos[]{JAR,BAD}){p.select("smoke_kitchen:pickling_crock");tap(p,a.below());}for(String[] pair:new String[][]{{"minecraft:furnace","0"},{"smoke_kitchen:hand_mill","1"},{"smoke_kitchen:cutting_board","2"},{"smoke_kitchen:drying_rack","3"}}){var at=new BlockPos[]{FURNACE,MILL,BOARD,RACK}[Integer.parseInt(pair[1])];p.select(pair[0]);tap(p,at.below());}
            for(int i=0;i<3;i++)p.s.runCommand("summon minecraft:pig -4.5 100 1.5 {NoAI:1b}");c.waitTicks(8);FirstMealFlowTest.kill(p,EntityType.PIG,new Vec3(-4.5,100,1.5));check(p.count("porkchop")>=3&&p.count("smoke_kitchen:rendered_fat")==3,"Actual axe kills give pork and pig fat, not granted meat");p.s.runCommand("setblock -5 100 3 smoke_kitchen:salt_ore");near(p,ORE);p.select("stone_pickaxe");p.mine(ORE);put(p,"salt_ore_chunk",MILL,2);p.emptyHand();tap(p,MILL);tap(p,MILL);take(p,MILL);check(p.count("smoke_kitchen:salt_crystals")==8,"Actual mined ore is really milled");put(p,"salt_crystals",MILL,4);put(p,"empty_jar",MILL,1);p.emptyHand();tap(p,MILL);take(p,MILL);
            int raw=p.count("porkchop");put(p,"minecraft:porkchop",JAR,1);check(p.count("porkchop")==raw&&observe(p,s->be(s,JAR).isEmpty()),"Whole pork is rejected without consumption");p.select("porkchop");cell(p,0);check(p.count("porkchop")==raw&&observe(p,s->be(s,RACK).isEmpty()),"Untreated pork cannot directly dry");
            p.select("smoke_kitchen:stone_knife");for(int i=0;i<5&&!observe(p,s->be(s,BOARD).cut==CookingBatch.Cut.SLICE);i++){c.getInput().holdKey(o->o.keyShift);tap(p,BOARD);c.getInput().releaseKey(o->o.keyShift);}check(observe(p,s->be(s,BOARD).cut==CookingBatch.Cut.SLICE),"Sneak knife actions select real slices");for(int i=0;i<3;i++){p.select("porkchop",x->!data(x).contains("kitchen_cut"));tap(p,BOARD);put(p,"stone_knife",BOARD,4);}for(int i=0;i<2;i++){p.select("porkchop",x->data(x).getStringOr("kitchen_cut","").equals("SLICE"));tap(p,JAR);}p.select("porkchop",x->data(x).getStringOr("kitchen_cut","").equals("SLICE"));tap(p,BAD);put(p,"salt",JAR,1);put(p,"salt",BAD,2);check(p.count("smoke_kitchen:empty_jar")==4,"Exactly4 actual salt doses return their real jar");p.s.runOnServer(s->{for(int i=0;i<2;i++)dates.add(data(be(s,JAR).items.get(i)).getLongOr("kitchen_prepared",-1));});p.emptyHand();tap(p,JAR);tap(p,BAD);photo(p,"actual-sealed-curing",JAR);waitWorld(p,600,"密封腌制");p.emptyHand();tap(p,JAR);take(p,JAR);p.select("smoke_kitchen:salting_pork");curingAtTake[0]=c.computeOnClient(m->MeatCuring.progress(m.player.getMainHandItem()));waitWorld(p,400,"开盖与携带暂停");p.select("smoke_kitchen:salting_pork");check(c.computeOnClient(m->MeatCuring.progress(m.player.getMainHandItem()))==curingAtTake[0],"Carry time cannot advance curing");tap(p,JAR);p.emptyHand();tap(p,JAR);p.select("smoke_kitchen:recipe_book");c.runOnClient(m->m.gameMode.useItem(m.player,InteractionHand.MAIN_HAND));c.waitTicks(5);c.takeScreenshot("curing-actual-guide-0.1.23");p.closeMenu();
        }
        try(var w=save.open()){
            var p=new SurvivalPlayer(c,w.getServer());c.waitTicks(12);waitWorld(p,2400,"实际腌透猪肉");check(observe(p,s->be(s,JAR).items.stream().limit(2).allMatch(x->x.is(KitchenContent.item("salted_pork")))),"Real curing finishes both good portions");p.emptyHand();tap(p,JAR);take(p,JAR);take(p,JAR);p.emptyHand();tap(p,BAD);take(p,BAD);for(int i=0;i<3;i++){int saltCount=i==2?2:1;p.select("smoke_kitchen:salted_pork",x->data(x).getIntOr("kitchen_meat_salt",0)==saltCount);cell(p,i);}waitWorld(p,1000,"实际风干肉条");photo(p,"actual-partial-meat-strips",RACK);p.emptyHand();cell(p,0);p.select("smoke_kitchen:partially_dried_salted_pork",x->data(x).getIntOr("kitchen_meat_salt",0)==1);int progress=c.computeOnClient(m->DryingRack.progress(m.player.getMainHandItem()));cell(p,3);check(observe(p,s->DryingRack.progress(be(s,RACK).items.get(3))>=progress),"Actual half-dry transfer retains meat progress");
        }
        try(var w=save.open()){
            var p=new SurvivalPlayer(c,w.getServer());c.waitTicks(12);waitWorld(p,4200,"风干至可加热阶段");check(observe(p,s->be(s,RACK).items.get(3).is(KitchenContent.item("dried_salted_pork"))),"Actual meat needs full240-second drying");photo(p,"actual-dried-meat-strips",RACK);p.emptyHand();cell(p,2);p.emptyHand();tap(p,FURNACE);p.putInMenu("smoke_kitchen:dried_salted_pork",0,1);p.putInMenu("coal",1,1);p.closeMenu();waitWorld(p,250,"过盐肉加热负例");check(observe(p,s->{var f=(net.minecraft.world.level.block.entity.AbstractFurnaceBlockEntity)s.overworld().getBlockEntity(FURNACE);return f.getItem(0).is(KitchenContent.item("dried_salted_pork"))&&f.getItem(2).isEmpty();}),"Actual furnace preserves oversalted input and produces no cleared-quality meal");p.emptyHand();tap(p,FURNACE);c.takeScreenshot("curing-actual-oversalt-furnace-rejection-0.1.23");p.slot(0,0,ContainerInput.QUICK_MOVE);p.closeMenu();p.select("smoke_kitchen:dried_salted_pork");p.s.runCommand("tp @a 10.5 100 6.5");c.waitTicks(5);c.runOnClient(m->m.player.drop(false));c.waitTicks(5);p.emptyHand();cell(p,1);p.emptyHand();cell(p,3);cookOne(p);cookOne(p);check(p.count("smoke_kitchen:cooked_salted_pork")==2,"Both actual good strips are heated into cooked food");p.s.runOnServer(s->{for(var x:s.getPlayerList().getPlayers().getFirst().getInventory().getNonEquipmentItems())if(x.is(KitchenContent.item("cooked_salted_pork")))check(dates.contains(data(x).getLongOr("kitchen_prepared",-2)),"Actual furnace output keeps one original preparation date");});p.s.runOnServer(s->s.getPlayerList().getPlayers().getFirst().getFoodData().setFoodLevel(8));p.select("smoke_kitchen:cooked_salted_pork");c.runOnClient(m->m.player.setXRot(-70));check(c.computeOnClient(m->m.player.getMainHandItem().has(DataComponents.FOOD)&&m.player.getMainHandItem().has(DataComponents.CONSUMABLE)),"Actual heated product must expose normal food/consumable components");int before=p.count("smoke_kitchen:cooked_salted_pork");c.getInput().holdKey(o->o.keyUse);c.waitTicks(35);c.getInput().releaseKey(o->o.keyUse);c.waitTicks(5);check(p.count("smoke_kitchen:cooked_salted_pork")==before-1,"Actual held-use eats one cooked preserved strip");check(observe(p,s->s.getPlayerList().getPlayers().getFirst().getFoodData().getFoodLevel()>8),"Real eating restores hunger");photo(p,"actual-cooked-and-eaten",FURNACE);
        }
        try(var w=save.open()){var p=new SurvivalPlayer(c,w.getServer());c.waitTicks(12);check(p.count("smoke_kitchen:cooked_salted_pork")==1,"Third real reopen retains the uneaten cooked strip");photo(p,"final-actual-reopen",RACK);}
    }
}
